# Handle commas safely:
# - If both ',' and '.' appear, treat ',' as a thousands separator and remove it (e.g., "1,234.5" -> "1234.5").
# - If only ',' appears, treat it as a decimal comma (e.g., "12,34" -> "12.34").
if ',' in s:
    if '.' in s:
        s = s.replace(',', '')
    else:
        s = s.replace(',', '.')
